/* NDR Trust website — shared script for every page (generated by gen/build.py from the single-page script). */
/* ===== Donation settings — edit these two lines only =====
   UPI_VPA: the Trust's UPI ID (e.g. "trustname@ujjivan"). Leave "" to hide UPI and show bank transfer only.
   UPI_QR_MODE: "generate" builds a QR (with the amount) in the browser using /js/qrcode.min.js;
                "image" shows the bank-issued QR uploaded to /images/payment/upi-qr.png instead. */
const UPI_VPA = "";
const UPI_QR_MODE = "generate";
const UPI_QR_IMAGE = "/images/payment/upi-qr.png";
const TRUST_PAYEE_NAME = "Narain Dass Rastogi Charitable Trust";
const TRUST_EMAIL = "naraindassrastogicharitabletrust@outlook.com";
// Google Apps Script web app (stores every submission in the Trust's Google Sheet and emails TRUST_EMAIL).
// Leave empty to fall back to the visitor's email app.
const BACKEND_URL = "";
function newRef() {
  const d = new Date();
  return 'NDR-' + String(d.getFullYear()).slice(2) + String(d.getMonth() + 1).padStart(2, '0') + String(d.getDate()).padStart(2, '0') + '-' + Math.floor(1000 + Math.random() * 9000);
}
function postToBackend(payload) {
  if (!BACKEND_URL) return Promise.resolve(null);
  return fetch(BACKEND_URL, { method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify(payload) })
    .then(function (r) { return r.json(); })
    .then(function (j) { return j && j.ok ? j : null; })
    .catch(function () { return null; });
}
function toast(en, hi) {
  let t = document.getElementById('ndrToast');
  if (!t) {
    t = document.createElement('div');
    t.id = 'ndrToast';
    t.setAttribute('role', 'status');
    t.className = 'fixed bottom-5 left-1/2 -translate-x-1/2 z-[70] max-w-md w-[calc(100%-2rem)] px-5 py-4 rounded-2xl bg-ink text-white text-sm shadow-xl';
    document.body.appendChild(t);
  }
  t.textContent = document.documentElement.classList.contains('lang-hi') ? hi : en;
  t.style.display = 'block';
  clearTimeout(t._h);
  t._h = setTimeout(function () { t.style.display = 'none'; }, 7000);
}

/* ===== Language (EN / हिं): persisted in localStorage, sets <html lang> ===== */
function isHi() { return document.documentElement.classList.contains('lang-hi'); }
function t(en, hi) { return isHi() ? hi : en; }
function applyLanguage() {
  const hi = isHi();
  document.documentElement.setAttribute('lang', hi ? 'hi' : 'en');
  const btn = document.getElementById('langToggleBtn');
  if (btn) btn.setAttribute('aria-pressed', hi ? 'true' : 'false');
  document.querySelectorAll('option[data-hi]').forEach(function (o) {
    if (!o.hasAttribute('data-en')) o.setAttribute('data-en', o.textContent);
    o.textContent = hi ? o.getAttribute('data-hi') : o.getAttribute('data-en');
  });
  document.querySelectorAll('[data-ph-hi]').forEach(function (el) {
    if (!el.hasAttribute('data-ph-en')) el.setAttribute('data-ph-en', el.getAttribute('placeholder') || '');
    el.setAttribute('placeholder', hi ? el.getAttribute('data-ph-hi') : el.getAttribute('data-ph-en'));
  });
  const mb = document.getElementById('menuBtn');
  if (mb) mb.setAttribute('aria-label', mb.getAttribute('aria-expanded') === 'true' ? t('Close menu', 'मेन्यू बंद करें') : t('Open menu', 'मेन्यू खोलें'));
  const fb = document.getElementById('facultyMoreBtn');
  if (fb) fb.textContent = t('Show all ' + fb.getAttribute('data-count') + ' faculty & staff', 'सभी ' + fb.getAttribute('data-count') + ' शिक्षक व कर्मचारी देखें');
  const lb = document.getElementById('lightbox');
  if (lb) {
    lb.setAttribute('aria-label', t('Photo viewer', 'फ़ोटो दर्शक'));
    document.getElementById('lbClose').setAttribute('aria-label', t('Close photo', 'फ़ोटो बंद करें'));
    document.getElementById('lbPrev').setAttribute('aria-label', t('Previous photo', 'पिछली फ़ोटो'));
    document.getElementById('lbNext').setAttribute('aria-label', t('Next photo', 'अगली फ़ोटो'));
  }
}
function toggleLanguage() {
  const hi = document.documentElement.classList.toggle('lang-hi');
  try { localStorage.setItem('ndr-lang', hi ? 'hi' : 'en'); } catch (e) {}
  applyLanguage();
}

/* ===== Mobile navigation (below xl) ===== */
function setMobileMenu(open, returnFocus) {
  const menu = document.getElementById('mobileMenu');
  const btn = document.getElementById('menuBtn');
  if (!menu || !btn) return;
  menu.classList.toggle('hidden', !open);
  btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  document.getElementById('menuIconOpen').classList.toggle('hidden', open);
  document.getElementById('menuIconClose').classList.toggle('hidden', !open);
  btn.setAttribute('aria-label', open ? t('Close menu', 'मेन्यू बंद करें') : t('Open menu', 'मेन्यू खोलें'));
  if (open) { const first = menu.querySelector('a'); if (first) first.focus(); }
  else if (returnFocus) btn.focus();
}
function closeMobileMenu() { setMobileMenu(false, false); }
(function () {
  const btn = document.getElementById('menuBtn');
  const menu = document.getElementById('mobileMenu');
  if (!btn || !menu) return;
  btn.addEventListener('click', function () { setMobileMenu(btn.getAttribute('aria-expanded') !== 'true', true); });
  menu.addEventListener('click', function (e) { if (e.target.closest('a')) setMobileMenu(false, false); });
  document.addEventListener('click', function (e) {
    if (btn.getAttribute('aria-expanded') === 'true' && !menu.contains(e.target) && !btn.contains(e.target)) setMobileMenu(false, false);
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && btn.getAttribute('aria-expanded') === 'true') setMobileMenu(false, true);
  });
  if (window.matchMedia) {
    const mq = window.matchMedia('(min-width: 1280px)');
    const onMq = function () { if (mq.matches) setMobileMenu(false, false); };
    if (mq.addEventListener) mq.addEventListener('change', onMq); else if (mq.addListener) mq.addListener(onMq);
  }
})();

/* ===== Photo lightbox (campus set + benefactor photo); links stay as no-JS fallback ===== */
(function () {
  const box = document.getElementById('lightbox');
  if (!box) return;
  const img = document.getElementById('lbImg');
  const cap = document.getElementById('lbCap');
  const count = document.getElementById('lbCount');
  const prev = document.getElementById('lbPrev');
  const next = document.getElementById('lbNext');
  const close = document.getElementById('lbClose');
  let set = [], idx = 0, trigger = null, touchX = null, touchY = null;
  function groupOf(a) { return Array.prototype.slice.call(document.querySelectorAll('a[data-lightbox="' + a.getAttribute('data-lightbox') + '"]')); }
  function show(i) {
    idx = (i + set.length) % set.length;
    const a = set[idx];
    const thumb = a.querySelector('img');
    const fig = a.closest('figure');
    const fc = fig ? fig.querySelector('figcaption') : null;
    img.src = a.getAttribute('href');
    img.alt = thumb ? thumb.getAttribute('alt') || '' : '';
    cap.innerHTML = fc ? fc.innerHTML : esc(a.getAttribute('data-caption') || img.alt);
    const multi = set.length > 1;
    prev.classList.toggle('hidden', !multi);
    next.classList.toggle('hidden', !multi);
    count.textContent = multi ? (idx + 1) + ' / ' + set.length : '';
  }
  function open(a) {
    trigger = a; set = groupOf(a); show(set.indexOf(a));
    box.classList.remove('hidden'); box.classList.add('flex');
    box.setAttribute('aria-hidden', 'false');
    document.body.classList.add('lb-lock');
    close.focus();
  }
  function shut() {
    box.classList.add('hidden'); box.classList.remove('flex');
    box.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('lb-lock');
    img.removeAttribute('src');
    if (trigger) trigger.focus();
  }
  document.addEventListener('click', function (e) {
    const a = e.target.closest('a[data-lightbox]');
    if (!a || e.metaKey || e.ctrlKey || e.shiftKey || e.button === 1) return;
    e.preventDefault();
    open(a);
  });
  close.addEventListener('click', shut);
  prev.addEventListener('click', function () { show(idx - 1); });
  next.addEventListener('click', function () { show(idx + 1); });
  box.addEventListener('click', function (e) { if (e.target === box || e.target.tagName === 'FIGURE') shut(); });
  document.addEventListener('keydown', function (e) {
    if (box.classList.contains('hidden')) return;
    if (e.key === 'Escape') { e.preventDefault(); shut(); }
    else if (e.key === 'ArrowLeft' && set.length > 1) { e.preventDefault(); show(idx - 1); }
    else if (e.key === 'ArrowRight' && set.length > 1) { e.preventDefault(); show(idx + 1); }
    else if (e.key === 'Tab') {
      const f = [close, prev, next].filter(function (b) { return !b.classList.contains('hidden'); });
      const i = f.indexOf(document.activeElement);
      e.preventDefault();
      const n = e.shiftKey ? (i <= 0 ? f.length - 1 : i - 1) : (i === -1 || i === f.length - 1 ? 0 : i + 1);
      f[n].focus();
    }
  });
  box.addEventListener('touchstart', function (e) {
    if (e.touches.length === 1) { touchX = e.touches[0].clientX; touchY = e.touches[0].clientY; }
  }, { passive: true });
  box.addEventListener('touchend', function (e) {
    if (touchX === null || set.length < 2) { touchX = null; return; }
    const dx = e.changedTouches[0].clientX - touchX;
    const dy = e.changedTouches[0].clientY - touchY;
    touchX = null;
    if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy)) show(idx + (dx < 0 ? 1 : -1));
  });
})();
function toggleCommitteeDrawer() {
  const drawer = document.getElementById('committeeDrawer');
  const chevron = document.getElementById('drawerChevron');
  drawer.classList.toggle('hidden');
  chevron.classList.toggle('rotate-180');
}
function openDossierModal(packName) {
  const modal = document.getElementById('dossierModal');
  document.getElementById('modalTitle').textContent = packName || 'Request Statutory Dossier';
  modal.classList.remove('hidden');
  modal.classList.add('flex');
}
function closeDossierModal() {
  const modal = document.getElementById('dossierModal');
  modal.classList.add('hidden');
  modal.classList.remove('flex');
}
function submitDossierRequest(e) {
  e.preventDefault();
  const name = document.getElementById('reqName').value;
  const org = document.getElementById('reqOrg').value;
  const contact = document.getElementById('reqContact').value;
  const pack = document.getElementById('reqPack').value;
  const purpose = document.getElementById('reqPurpose').value;
  const subject = encodeURIComponent('[Dossier Request] ' + pack + ' — ' + org);
  const body = encodeURIComponent(
    'To: Board of Trustees, Narain Dass Rastogi Charitable Trust\n\n' +
    'Requester Name: ' + name + '\n' +
    'Organization: ' + org + '\n' +
    'Contact: ' + contact + '\n' +
    'Requested Pack: ' + pack + '\n' +
    'Purpose: ' + purpose + '\n'
  );
  const ref = newRef();
  postToBackend({ form: 'enquiry', ref: ref, type: 'Dossier request', name: name, org: org,
    email: /@/.test(contact) ? contact : '', mobile: /@/.test(contact) ? '' : contact, pack: pack, message: purpose, website: (document.getElementById('hpDossier') || {}).value || '' })
    .then(function (res) {
      closeDossierModal();
      if (res) {
        toast('Thank you. Your request (' + res.ref + ') has reached the Trust. We will reply within 3 working days.',
              'धन्यवाद। आपका अनुरोध (' + res.ref + ') ट्रस्ट को मिल गया है। हम 3 कार्यदिवस में उत्तर देंगे।');
      } else {
        window.location.href = 'mailto:' + TRUST_EMAIL + '?subject=' + subject + '&body=' + body;
      }
    });
}

/* ===== Faculty directory from /data/faculty.json (static fallback stays if fetch fails) ===== */
function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
  });
}
function renderFaculty(data) {
  const list = (data && data.facultyMembers) || [];
  if (!list.length) return;
  const grid = document.getElementById('facultyGrid');
  const SHOW = 6;
  grid.innerHTML = list.map(function (m, i) {
    const avatar = m.photo
      ? '<img src="' + esc(m.photo) + '" alt="' + esc(m.name) + '" loading="lazy" class="w-11 h-11 rounded-xl object-cover border border-ink/10 flex-shrink-0" />'
      : '<span class="w-11 h-11 rounded-xl bg-crimson/10 text-crimson font-bold text-sm flex items-center justify-center flex-shrink-0">' + esc(m.initials || '') + '</span>';
    const subjects = (m.subjects || []).join(', ');
    return '<div class="p-4 rounded-2xl bg-white border border-ink/10 flex gap-3 items-start' + (i >= SHOW ? ' fac-more hidden' : '') + '">' + avatar +
      '<div class="min-w-0"><div class="text-[11px] font-bold text-crimson uppercase">' + esc(m.badge || m.department || '') + '</div>' +
      '<div class="font-bold text-ink mt-0.5">' + esc(m.name) + '</div>' +
      '<div class="text-xs text-slate mt-0.5">' + esc(m.role || '') + (subjects ? ' • ' + esc(subjects) : '') + '</div>' +
      (m.qualifications ? '<div class="text-[11px] text-slate mt-1">' + esc(m.qualifications) + '</div>' : '') +
      (m.experience ? '<div class="text-[11px] text-slate">' + esc(m.experience) + '</div>' : '') +
      '</div></div>';
  }).join('');
  if (list.length > SHOW) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'mt-5 px-5 py-2.5 rounded-full text-xs font-semibold bg-white border border-ink/15 text-ink hover:bg-sand transition';
    btn.id = 'facultyMoreBtn';
    btn.setAttribute('data-count', String(list.length));
    btn.textContent = t('Show all ' + list.length + ' faculty & staff', 'सभी ' + list.length + ' शिक्षक व कर्मचारी देखें');
    btn.onclick = function () {
      grid.querySelectorAll('.fac-more').forEach(function (el) { el.classList.remove('hidden'); });
      btn.remove();
    };
    grid.parentNode.appendChild(btn);
  }
}
if (document.getElementById('facultyGrid')) fetch('/data/faculty.json').then(function (r) { return r.ok ? r.json() : null; }).then(renderFaculty).catch(function () {});

/* ===== Donate: KYC first, then payment, then UTR email ===== */
let donor = null;
const PAN_RE = /^[A-Z]{5}[0-9]{4}[A-Z]$/;
const PIN_RE = /^[1-9][0-9]{5}$/;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

function val(id) { return document.getElementById(id).value.trim(); }
function mark(id, errId, ok) {
  document.getElementById(id).classList.toggle('invalid', !ok);
  document.getElementById(errId).classList.toggle('show', !ok);
  return ok;
}
function normMobile(v) {
  let d = v.replace(/[\s\-()]/g, '');
  if (d.indexOf('+91') === 0) d = d.slice(3);
  else if (d.length === 12 && d.indexOf('91') === 0) d = d.slice(2);
  else if (d.length === 11 && d.charAt(0) === '0') d = d.slice(1);
  return d;
}
function setDots(n) {
  [1, 2, 3].forEach(function (i) {
    const el = document.getElementById('dot' + i);
    el.className = 'step-dot ' + (i <= n ? 'bg-crimson text-white' : 'bg-white border border-ink/15 text-slate');
  });
}
function submitKyc(e) {
  e.preventDefault();
  const pan = val('dPan').toUpperCase();
  document.getElementById('dPan').value = pan;
  const mobile = normMobile(val('dMobile'));
  const amountRaw = val('dAmount');
  const amount = Number(amountRaw);
  let ok = true;
  ok = mark('dName', 'eName', val('dName').length >= 3) && ok;
  ok = mark('dPan', 'ePan', PAN_RE.test(pan)) && ok;
  ok = mark('dAmount', 'eAmount', /^\d+$/.test(amountRaw) && amount >= 1) && ok;
  ok = mark('dAddress', 'eAddress', val('dAddress').length >= 8) && ok;
  ok = mark('dPin', 'ePin', PIN_RE.test(val('dPin'))) && ok;
  ok = mark('dMobile', 'eMobile', /^[6-9][0-9]{9}$/.test(mobile)) && ok;
  ok = mark('dEmail', 'eEmail', EMAIL_RE.test(val('dEmail'))) && ok;
  const consent = document.getElementById('dConsent').checked;
  document.getElementById('eConsent').classList.toggle('show', !consent);
  ok = consent && ok;
  if (!ok) {
    const first = document.querySelector('#kycForm .invalid') || document.getElementById('dConsent');
    if (first) first.focus();
    return;
  }
  donor = {
    name: val('dName'), pan: pan, address: val('dAddress'), pin: val('dPin'),
    mobile: mobile, email: val('dEmail'), amount: amount, purpose: val('dPurpose')
  };
  donor.ref = newRef();
  postToBackend({ form: 'donation', ref: donor.ref, name: donor.name, pan: donor.pan, address: donor.address, pin: donor.pin,
    mobile: donor.mobile, email: donor.email, amount: donor.amount, purpose: donor.purpose, consent: true,
    website: (document.getElementById('hpKyc') || {}).value || '' });
  showPayment();
}
function inr(n) { return '₹' + Number(n).toLocaleString('en-IN'); }
function showPayment() {
  document.getElementById('payAmountLabel').textContent = inr(donor.amount);
  document.getElementById('kycSummary').textContent =
    donor.name + ' • PAN ' + donor.pan + ' • ' + donor.purpose;
  const upiBlock = document.getElementById('upiBlock');
  const bankBlock = document.getElementById('bankBlock');
  if (UPI_VPA) {
    upiBlock.classList.remove('hidden');
    bankBlock.classList.remove('md:col-span-2');
    setupUpi();
  } else {
    upiBlock.classList.add('hidden');
    bankBlock.classList.add('md:col-span-2');
  }
  document.getElementById('kycForm').classList.add('hidden');
  document.getElementById('payStep').classList.remove('hidden');
  setDots(2);
  document.getElementById('payStep').scrollIntoView({ behavior: 'smooth', block: 'start' });
}
function upiUri() {
  return 'upi://pay?pa=' + UPI_VPA.trim() +
    '&pn=' + encodeURIComponent(TRUST_PAYEE_NAME) +
    '&am=' + encodeURIComponent(String(donor.amount)) +
    '&cu=INR&tn=' + encodeURIComponent('Donation');
}
function setupUpi() {
  const uri = upiUri();
  document.getElementById('upiLink').href = uri;
  document.getElementById('upiVpaLabel').textContent = UPI_VPA;
  const box = document.getElementById('upiQr');
  function showImage() {
    box.innerHTML = '<img src="' + UPI_QR_IMAGE + '" alt="UPI QR code for donations to the Trust" class="w-full h-full object-contain" />';
  }
  if (UPI_QR_MODE === 'image') { showImage(); return; }
  function draw() {
    try {
      const qr = qrcode(0, 'M');
      qr.addData(uri);
      qr.make();
      box.innerHTML = qr.createSvgTag({ cellSize: 4, margin: 2, scalable: true });
    } catch (err) { showImage(); }
  }
  if (window.qrcode) { draw(); return; }
  const s = document.createElement('script');
  s.src = '/js/qrcode.min.js';
  s.onload = draw;
  s.onerror = showImage;
  document.head.appendChild(s);
}
function editKyc() {
  document.getElementById('payStep').classList.add('hidden');
  document.getElementById('utrStep').classList.add('hidden');
  document.getElementById('kycForm').classList.remove('hidden');
  setDots(1);
  document.getElementById('kycForm').scrollIntoView({ behavior: 'smooth', block: 'start' });
}
function showStep3() {
  document.getElementById('utrStep').classList.remove('hidden');
  if (UPI_VPA) document.getElementById('dMode').value = 'UPI';
  setDots(3);
  document.getElementById('utrStep').scrollIntoView({ behavior: 'smooth', block: 'start' });
}
function sendReceiptEmail(e) {
  e.preventDefault();
  if (!donor) { editKyc(); return; }
  const utr = val('dUtr').toUpperCase().replace(/\s+/g, '');
  if (!mark('dUtr', 'eUtr', /^[A-Z0-9]{6,35}$/.test(utr))) { document.getElementById('dUtr').focus(); return; }
  const subject = '80G receipt request — ' + donor.name + ' — ' + inr(donor.amount) + ' — UTR ' + utr;
  const body =
    'Dear Trustees,\n\nPlease issue an 80G receipt for my donation to Narain Dass Rastogi Charitable Trust.\n\n' +
    'Full name: ' + donor.name + '\n' +
    'PAN: ' + donor.pan + '\n' +
    'Address: ' + donor.address + '\n' +
    'PIN: ' + donor.pin + '\n' +
    'Mobile: ' + donor.mobile + '\n' +
    'Email: ' + donor.email + '\n' +
    'Amount: ' + inr(donor.amount) + '\n' +
    'Purpose: ' + donor.purpose + '\n' +
    'Paid by: ' + val('dMode') + '\n' +
    'Date of payment: ' + (val('dPaidOn') || '-') + '\n' +
    'UTR / transaction reference: ' + utr + '\n\n' +
    'I confirm the above details are correct for my 80G receipt.\n';
  const btn = e.submitter || document.querySelector('#utrStep button[type=submit]');
  if (btn) btn.disabled = true;
  postToBackend({ form: 'donation', ref: donor.ref, name: donor.name, pan: donor.pan, address: donor.address, pin: donor.pin,
    mobile: donor.mobile, email: donor.email, amount: donor.amount, purpose: donor.purpose, consent: true,
    mode: val('dMode'), paidOn: val('dPaidOn'), utr: utr })
    .then(function (res) {
      if (btn) btn.disabled = false;
      if (res) {
        toast('Thank you, ' + donor.name + '. Your payment details (' + res.ref + ') are recorded. Your 80G receipt will follow after the Trust verifies the credit.',
              'धन्यवाद, ' + donor.name + '। आपके भुगतान का विवरण (' + res.ref + ') दर्ज हो गया है। राशि की पुष्टि के बाद 80G रसीद भेजी जाएगी।');
      } else {
        window.location.href = 'mailto:' + TRUST_EMAIL + '?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(body);
      }
    });
}

/* Copy buttons */
document.addEventListener('click', function (e) {
  const btn = e.target.closest('.copy-btn');
  if (!btn) return;
  const text = document.getElementById(btn.getAttribute('data-copy')).textContent.trim();
  function done() { const orig = btn.innerHTML; btn.textContent = t('Copied', 'कॉपी हो गया'); setTimeout(function () { btn.innerHTML = orig; }, 1500); }
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(text).then(done).catch(fallback);
  } else { fallback(); }
  function fallback() {
    const ta = document.createElement('textarea');
    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); done(); } catch (err) {}
    document.body.removeChild(ta);
  }
});

/* ===== Founder tribute: Read more / और पढ़ें ===== */
(function () {
  const btn = document.getElementById('founderToggle');
  const more = document.getElementById('founderMore');
  if (!btn || !more) return;
  btn.addEventListener('click', function () {
    const open = btn.getAttribute('aria-expanded') !== 'true';
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    more.hidden = !open;
  });
})();

/* ===== Committee drawer: keep aria-expanded in sync ===== */
(function () {
  const b = document.getElementById('committeeBtn');
  if (!b) return;
  b.addEventListener('click', function () {
    const d = document.getElementById('committeeDrawer');
    b.setAttribute('aria-expanded', d && !d.classList.contains('hidden') ? 'true' : 'false');
  });
})();

/* ===== Enquiry forms (admissions, alumni, volunteer, general) =====
   Each form: class="enquiry-form" data-enquiry="<type>" and fields named name/org/email/mobile/pack/message,
   plus the honeypot input name="website". Posts form:'enquiry' to BACKEND_URL; falls back to mailto. */
function submitEnquiry(e) {
  e.preventDefault();
  const f = e.target;
  const type = f.getAttribute('data-enquiry') || 'Enquiry';
  function v(n) { const el = f.elements[n]; return el ? String(el.value || '').trim() : ''; }
  let ok = true, first = null;
  Array.prototype.forEach.call(f.querySelectorAll('[data-req]'), function (el) {
    const kind = el.getAttribute('data-req');
    const val = String(el.value || '').trim();
    let good = val.length >= 2;
    if (kind === 'email') good = EMAIL_RE.test(val);
    else if (kind === 'mobile') good = /^[6-9][0-9]{9}$/.test(normMobile(val));
    else if (kind === 'text') good = val.length >= 5;
    el.classList.toggle('invalid', !good);
    const er = f.querySelector('[data-err-for="' + el.name + '"]');
    if (er) er.classList.toggle('show', !good);
    if (!good && !first) first = el;
    ok = ok && good;
  });
  if (!ok) { if (first) first.focus(); return; }
  const mobile = v('mobile') ? normMobile(v('mobile')) : '';
  const payload = { form: 'enquiry', ref: newRef(), type: type, name: v('name'), org: v('org'), email: v('email'),
    mobile: mobile, pack: v('pack'), message: v('message'), website: v('website') };
  const btn = f.querySelector('button[type=submit]');
  if (btn) btn.disabled = true;
  postToBackend(payload).then(function (res) {
    if (btn) btn.disabled = false;
    if (res) {
      f.reset();
      toast('Thank you. Your message (' + res.ref + ') has reached the Trust. We will reply within 3 working days.',
            'धन्यवाद। आपका संदेश (' + res.ref + ') ट्रस्ट को मिल गया है। हम 3 कार्यदिवस में उत्तर देंगे।');
    } else {
      const subject = '[' + type + '] ' + payload.name + ' — ' + payload.ref;
      const body = 'To: Narain Dass Rastogi Charitable Trust\n\n' +
        'Type: ' + type + '\n' +
        'Name: ' + payload.name + '\n' +
        (payload.org ? 'Organisation / city: ' + payload.org + '\n' : '') +
        (payload.email ? 'Email: ' + payload.email + '\n' : '') +
        (payload.mobile ? 'Mobile: ' + payload.mobile + '\n' : '') +
        (payload.pack ? 'Details: ' + payload.pack + '\n' : '') +
        '\n' + payload.message + '\n\nReference: ' + payload.ref + '\n';
      window.location.href = 'mailto:' + TRUST_EMAIL + '?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(body);
    }
  });
}

applyLanguage();
